                local t_onscreen, t_x, t_y = GetScreenCoordFromWorldCoord(coords.x,coords.y,coords.z+0.95)
                local b_onscreen, b_x, b_y = GetScreenCoordFromWorldCoord(coords.x,coords.y,coords.z-0.95)
    
