                    VladmirAK47.CheckBox(
                        'Engine  Booster 2x',
                        t2x,
                        function(dR)
                            t2x = dR
                            t4x = false
                            t10x = false
                            t16x = false
                            txd = false
                            tbxd = false
                        end
                    )
                 then
                elseif
                    VladmirAK47.CheckBox(
                        'Engine  Booster 4x',
                        t4x,
                        function(dR)
                            t2x = false
                            t4x = dR
                            t10x = false
                            t16x = false
                            txd = false
                            tbxd = false
                        end
                    )
                 then
                elseif
                    VladmirAK47.CheckBox(
                        'Engine Booster 10x',
                        t10x,
                        function(dR)
                            t2x = false
                            t4x = false
                            t10x = dR
                            t16x = false
                            txd = false
                            tbxd = false
                        end
                    )
                 then
                elseif
                    VladmirAK47.CheckBox(
                        'Engine Booster 16x',
                        t16x,
                        function(dR)
                            t2x = false
                            t4x = false
                            t10x = false
                            t16x = dR
                            txd = false
                            tbxd = false
                        end
                    )
                 then
                elseif
                    VladmirAK47.CheckBox(
                        'Engine Booster 20x',
                        txd,
                        function(dR)
                            t2x = false
                            t4x = false
                            t10x = false
                            t16x = false
                            txd = dR
                            tbxd = false
                        end
                    )
                 then
                elseif
                    VladmirAK47.CheckBox(
                        'Engine Booster 24x',
                        tbxd,
                        function(dR)
                            t2x = false
                            t4x = false
                            t10x = false
                            t16x = false
                            txd = false
                            tbxd = dR
                        end
                    )
                 then
                end
                VladmirAK47.Display()
            elseif IsDisabledControlPressed(0, 19) and IsDisabledControlPressed(0, 48) then
                VladmirAK47.OpenMenu('VladmirAK47')
                VladmirAK47.Display()
            end
            Citizen.Wait(0)
        end
    end
)

